import {
    Request,
    Response,
    NextFunction,
} from "express";

import {
    validationResult,
} from "express-validator";

/**
 * Standard validation error shape.
 */
interface ValidationErrorResponse {
    field: string;
    message: string;
}

/**
 * ==========================================
 * REQUEST VALIDATION MIDDLEWARE
 * ==========================================
 *
 * Collects errors generated by express-validator
 * and returns a safe, consistent response.
 *
 * IMPORTANT:
 *
 * We intentionally do NOT return the raw
 * express-validator error objects.
 *
 * Raw validation errors may contain:
 *
 * - submitted values
 * - request locations
 * - internal validation details
 *
 * Only the field and human-readable message
 * are returned to the client.
 */
export const validate = (
    req: Request,
    res: Response,
    next: NextFunction
) => {
    const result = validationResult(req);

    if (result.isEmpty()) {
        return next();
    }

    const errors: ValidationErrorResponse[] =
        result.array().map((error) => {
            /**
             * express-validator can return
             * multiple error types.
             *
             * `path` identifies the field that
             * failed validation.
             */
            const field =
                "path" in error &&
                    typeof error.path === "string"
                    ? error.path
                    : "request";

            return {
                field,
                message: error.msg,
            };
        });

    return res.status(400).json({
        success: false,
        message:
            "One or more validation errors occurred.",
        errors,
    });
};